import RNA, random, multiprocessing as mp, sys
sub='((((....).)))'
# block of 6 with single-nt linkers (dots)
t6 = sub+'.'+sub+'.'+sub+'.'+sub+'.'+sub+'.'+sub   # 13*6 + 5 = 83
t5 = sub+'.'+sub+'.'+sub+'.'+sub+'.'+sub            # 13*5 + 4 = 69
def fold(s): return RNA.fold_compound(s).mfe()[0]
def worker(args):
    target, seed = args
    random.seed(seed)
    for _ in range(60):
        start=''.join(random.choice('ACGU') for _ in range(len(target)))
        seq,d=RNA.inverse_fold(start,target)
        if d==0 and fold(seq)==target:
            return (target,seq)
    return None
if __name__=='__main__':
    jobs=[]
    for s in range(200): jobs.append((t6,s))
    for s in range(200): jobs.append((t5,s))
    found6=[]; found5=[]
    with mp.Pool(48) as p:
        for r in p.imap_unordered(worker, jobs):
            if r:
                t,seq=r
                if t==t6 and len(found6)<8:
                    found6.append(seq); print('T6',seq,flush=True)
                elif t==t5 and len(found5)<8:
                    found5.append(seq); print('T5',seq,flush=True)
                if len(found6)>=8 and len(found5)>=8:
                    p.terminate(); break
    with open('/tmp/block_sols.txt','w') as f:
        for s in found6: f.write('6 '+s+'\n')
        for s in found5: f.write('5 '+s+'\n')
    print('DONE', len(found6), len(found5))
EOF
